sp_widget.client_script:
api.controller=function($window){

var c=this;

c.departmentSearch='';



c.explore=function(){

if(!c.departmentSearch)
return;



$window.location.href =
'/ev?id=department'+'&department='+encodeURIComponent(c.departmentSearch);

};

};

sp_widget.css:
.department-hero{

position:relative;

overflow:hidden;

min-height:420px;

border-radius:
30px 30px 30px 30px;

background:
linear-gradient(
135deg,
#041734,
#2148D2,
#5A82FF
);

padding:56px;

display:flex;

justify-content:space-between;

align-items:center;

gap:40px;

color:white;

}



/* OVERLAY */

.hero-overlay{

position:absolute;

right:-150px;

top:-120px;

width:460px;

height:460px;

border-radius:50%;

background:
rgba(
255,
255,
255,
.06
);

}



/* LEFT */

.hero-left{

flex:1;

max-width:620px;

position:relative;

z-index:2;

}



/* BADGE */

.hero-badge{

display:inline-flex;

padding:10px 18px;

border-radius:999px;

background:
rgba(
255,
255,
255,
.10
);

font-size:10px;

font-weight:800;

letter-spacing:1.5px;

}



/* TITLE */

.hero-left h1{

margin-top:24px;

font-size:48px;

line-height:1.05;

font-weight:900;

}



/* TEXT */

.hero-left p{

margin-top:18px;

font-size:15px;

line-height:1.8;

opacity:.92;

max-width:520px;

}



/* ACTION AREA */

.hero-actions{

margin-top:26px;

display:flex;

flex-direction:column;

gap:16px;

}



/* BACK */

.back-btn{

display:inline-flex;

align-items:center;

justify-content:center;

width:140px;

height:50px;

border-radius:16px;

background:
rgba(
255,
255,
255,
.12
);

backdrop-filter:
blur(20px);

text-decoration:none;

color:white;

font-size:13px;

font-weight:800;

transition:.25s;

}


.back-btn:hover{

transform:
translateY(-2px);

}


/* RIGHT */

.hero-right{

display:flex;

flex-direction:column;

gap:18px;

position:relative;

z-index:2;

}



.stat-card{

width:190px;

height:180px;

border-radius:26px;

background:
rgba(
255,
255,
255,
.12
);

backdrop-filter:
blur(20px);

display:flex;

justify-content:center;

align-items:center;

flex-direction:column;

}



.small{

height:140px;

}



.stat-number{

font-size:48px;

font-weight:900;

}



.stat-text{

margin-top:8px;

font-size:15px;

}



/* TABLET */

@media(max-width:900px){

.department-hero{

flex-direction:column;

text-align:center;

padding:42px 30px;

min-height:auto;

}

.hero-left{

max-width:100%;

}

.hero-left h1{

font-size:42px;

}

.hero-left p{

font-size:15px;

margin:auto;

}

.hero-actions{

align-items:center;

}

.hero-search{

flex-direction:column;

width:100%;

}

.hero-search input,
.hero-search button{

width:100%;

}

.hero-right{

flex-direction:row;

flex-wrap:wrap;

justify-content:center;

}

}



/* MOBILE */

@media(max-width:600px){

.department-hero{

padding:30px 18px;

}

.hero-left h1{

font-size:32px;

}

.hero-left p{

font-size:13px;

}

.hero-search input,
.hero-search button{

height:48px;

font-size:12px;

}

.back-btn{

width:100%;

}

.stat-card{

width:140px;

height:130px;

}

.stat-number{

font-size:36px;

}

.stat-text{

font-size:12px;

}

.hero-overlay{

width:260px;

height:260px;

}

}

sp_widget.script:
(function(){

data.departments=0;

data.employees=0;


/* departments */

var dep=
new GlideAggregate(
'x_1902481_employ_0_department'
);

dep.addAggregate(
'COUNT'
);

dep.query();

if(dep.next()){

data.departments=
dep.getAggregate(
'COUNT'
);

}


/* employees */

var emp=
new GlideAggregate(
'x_1902481_employ_0_employee'
);

emp.addAggregate(
'COUNT'
);

emp.query();

if(emp.next()){

data.employees=
emp.getAggregate(
'COUNT'
);

}

})();
